import assert from "node:assert/strict";
import { describe, it, mock } from "node:test";
import * as lexer from "./lexer.js";
import { parse } from "./parser.js";

describe("parse", () => {
  it("tokenizes the source exactly once", () => {
    const tokenize = mock.method(lexer, "tokenize");

    parse("# Title\n\nSome *emphasis* here.");

    assert.strictEqual(tokenize.mock.calls.length, 1);
