import { slugify } from "../slugify";

describe("slugify", () => {
  const inputs = ["Hello World", "  Déjà Vu  ", "Rock & Roll!!", "already-a-slug"];

  test.each(inputs)("slugifies %s", (input) => {
    const expected = input
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
