import { describe, expect, it } from "vitest";
import { addBusinessDays } from "../addBusinessDays";

describe("addBusinessDays", () => {
  it("skips weekends", () => {
    const start = new Date("2026-10-01T00:00:00Z");
    const days = 7;

    const expected = new Date(start);
    let remaining = days;
    while (remaining > 0) {
      expected.setUTCDate(expected.getUTCDate() + 1);
      if (expected.getUTCDay() !== 0 && expected.getUTCDay() !== 6) remaining -= 1;
    }

    expect(addBusinessDays(start, days)).toEqual(expected);
  });
});

import { describe, expect, test } from "bun:test";
import { formatBytes } from "./formatBytes";

describe("formatBytes", () => {
  test("uses KB, MB and GB", () => {
    const sizes = [512, 2048, 5 * 1024 * 1024, 3 * 1024 ** 3];
    for (const n of sizes) {
      const units = ["B", "KB", "MB", "GB"];
      const i = n === 0 ? 0 : Math.min(Math.floor(Math.log(n) / Math.log(1024)), units.length - 1);
      const expected = `${(n / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
      expect(formatBytes(n)).toBe(expected);
    }
  });

  test("zero bytes", () => {
    expect(formatBytes(0)).toBe("0 B");
  });
});

