import type { ReactElement, ReactNode } from "react";
import { MemoryRouter } from "react-router-dom";
import { ThemeProvider } from "../theme";

export function renderWithProviders(ui: ReactElement, options: RenderOptions & { route?: string } = {}) {
  const { route = "/", ...rest } = options;
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });

  function Wrapper({ children }: { children: ReactNode }) {
    return (
      <QueryClientProvider client={client}>
        <ThemeProvider>
          <MemoryRouter initialEntries={[route]}>{children}</MemoryRouter>
        </ThemeProvider>
      </QueryClientProvider>
    );
  }

  return render(ui, { wrapper: Wrapper, ...rest });
}

import { describe, expect, it } from "vitest";
import { wrap } from "../wrap";

describe("wrap", () => {
  it("wraps at the column without splitting words", () => {
    expect(wrap("the quick brown fox jumps over the lazy dog", 15)).toEqual([
      "the quick brown",
      "fox jumps over",
      "the lazy dog",
    ]);
  });

  it("never produces a line longer than the width unless a single word is", () => {
    const lines = wrap("a bb ccc dddd eeeee supercalifragilistic ff", 8);
    for (const line of lines) {
      if (!line.includes(" ")) continue;
      expect(line.length).toBeLessThanOrEqual(8);
    }
    expect(lines.join(" ")).toBe("a bb ccc dddd eeeee supercalifragilistic ff");
  });
});

